<source_code>
import java.util.*;
import java.io.*;

public class Solution {

    public static Long[][][] dp;

    public static long f(int p, int x, int lastTwoDigit, int len, String str, boolean started) {
        if (p == len) {
            if (started && (lastTwoDigit == 0 || lastTwoDigit == 25 || lastTwoDigit == 50 || lastTwoDigit == 75)) {
                return 1;
            }
            return 0;
        }
        if (dp[p][x][lastTwoDigit] != null) {
            return dp[p][x][lastTwoDigit];
        }
        long ans = 0;
        if (str.charAt(p) == 'X') {
            if (x != 10) {
                ans = f(p + 1, x, (lastTwoDigit % 10) * 10 + x, len, str, true);
            } else {
                for (int i = 0; i < 10; i++) {
                    ans += f(p + 1, i, (lastTwoDigit % 10) * 10 + i, len, str, true);
                }
            }
        } else if (str.charAt(p) == '_') {
            for (int i = 0; i < 10; i++) {
                ans += f(p + 1, x, (lastTwoDigit % 10) * 10 + i, len, str, true);
            }
        } else {
            int digit = str.charAt(p) - '0';
            ans += f(p + 1, x, (lastTwoDigit % 10) * 10 + digit, len, str, true);
        }

        return dp[p][x][lastTwoDigit] = ans;
    }

    public static void solve(InputReader in, PrintWriter out) {
        String str = in.next();
        int len = str.length();

        // Check for leading zero issues
        if (str.charAt(0) == '0') {
            out.println(0);
            return;
        }

        // Special case: single character
        if (len == 1) {
            if (str.charAt(0) == '0') {
                out.println(1);
            } else if (str.charAt(0) == '_' || str.charAt(0) == 'X') {
                out.println(1); // Only 0 is valid for single digit divisible by 25
            } else {
                int digit = str.charAt(0) - '0';
                out.println(digit == 0 ? 1 : 0);
            }
            return;
        }

        dp = new Long[len][11][100];

        long result = 0;

        // Handle first character specially to avoid leading zeros
        char firstChar = str.charAt(0);
        if (firstChar == 'X') {
            for (int i = 1; i < 10; i++) {
                result += f(1, i, i, len, str, true);
            }
        } else if (firstChar == '_') {
            for (int i = 1; i < 10; i++) {
                result += f(1, 10, i, len, str, true);
            }
        } else {
            int digit = firstChar - '0';
            if (digit != 0) {
                result = f(1, 10, digit, len, str, true);
            }
        }

        out.println(result);
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(in, out);
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}
